window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ea3c11546cb443d1"]={"versions": [{"id": "FIG-ea3c11546cb443d1", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb des AUTOSAR-Vorlagenmodells (Template Modeling Guide). Das Diagramm definiert den primitiven Datentyp <code>Identifier</code> sowie die Metaklasse <code>LiteralIdentifier</code> im Kontext der Profil-Erweiterung von UML-Kerntypen (<code>Kernel::LiteralString</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst drei Entitäten:</p>\n<ul class=\"fig-list\"><li><code>Identifier</code>: Primitiver Datentyp mit dem Stereotyp <code>«primitive»</code>, ohne explizit dargestellte Attribute oder Operationen.\n</li><li><code>Kernel::LiteralString</code>: Externe Metaklasse mit dem Stereotyp <code>«metaclass»</code>, die das öffentliche Attribut <code>+ value: String</code> deklariert.\n</li><li><code>LiteralIdentifier</code>: Eigene Metaklasse, die über eine gerichtete Abhängigkeit mit dem Stereotyp <code>«extends»</code> die Metaklasse <code>Kernel::LiteralString</code> erweitert.\n</li></ul>\n<p class=\"fig-p\">Zwischen <code>Identifier</code> und den anderen beiden Elementen ist im Diagramm keine direkte Beziehung modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es sind keine dynamischen Interaktionen, Zustandsübergänge oder Sequenzabläufe dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der primitive Typ <code>Identifier</code> dient als Basistyp für Bezeichner im AUTOSAR-Metamodell. Die Modellierung von <code>LiteralIdentifier</code> als Erweiterung (<code>«extends»</code>) von <code>Kernel::LiteralString</code> mit dem Attribut <code>value: String</code> definiert die syntaktische und typbezogene Repräsentation von Literalwerten für Bezeichner auf Metamodell-Ebene. Werkzeug- und Codegeneratoren müssen Bezeichner gemäß diesen Metamodell-Vorgaben als spezialisierte Literalstrings abbilden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-99a5aeab3f3843ab", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb des AUTOSAR-Vorlagenmodells (Template Modeling Guide). Das Diagramm definiert den primitiven Datentyp <code>Identifier</code> sowie die Metaklasse <code>LiteralIdentifier</code> im Kontext der Profil-Erweiterung von UML-Kerntypen (<code>Kernel::LiteralString</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst drei Entitäten:</p>\n<ul class=\"fig-list\"><li><code>Identifier</code>: Primitiver Datentyp mit dem Stereotyp <code>«primitive»</code>, ohne explizit dargestellte Attribute oder Operationen.\n</li><li><code>Kernel::LiteralString</code>: Externe Metaklasse mit dem Stereotyp <code>«metaclass»</code>, die das öffentliche Attribut <code>+ value: String</code> deklariert.\n</li><li><code>LiteralIdentifier</code>: Eigene Metaklasse, die über eine gerichtete Abhängigkeit mit dem Stereotyp <code>«extends»</code> die Metaklasse <code>Kernel::LiteralString</code> erweitert.\n</li></ul>\n<p class=\"fig-p\">Zwischen <code>Identifier</code> und den anderen beiden Elementen ist im Diagramm keine direkte Beziehung modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es sind keine dynamischen Interaktionen, Zustandsübergänge oder Sequenzabläufe dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der primitive Typ <code>Identifier</code> dient als Basistyp für Bezeichner im AUTOSAR-Metamodell. Die Modellierung von <code>LiteralIdentifier</code> als Erweiterung (<code>«extends»</code>) von <code>Kernel::LiteralString</code> mit dem Attribut <code>value: String</code> definiert die syntaktische und typbezogene Repräsentation von Literalwerten für Bezeichner auf Metamodell-Ebene. Werkzeug- und Codegeneratoren müssen Bezeichner gemäß diesen Metamodell-Vorgaben als spezialisierte Literalstrings abbilden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c8cda682e56bd53e", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb des AUTOSAR-Vorlagenmodells (Template Modeling Guide). Das Diagramm definiert den primitiven Datentyp <code>Identifier</code> sowie die Metaklasse <code>LiteralIdentifier</code> im Kontext der Profil-Erweiterung von UML-Kerntypen (<code>Kernel::LiteralString</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst drei Entitäten:</p>\n<ul class=\"fig-list\"><li><code>Identifier</code>: Primitiver Datentyp mit dem Stereotyp <code>«primitive»</code>, ohne explizit dargestellte Attribute oder Operationen.\n</li><li><code>Kernel::LiteralString</code>: Externe Metaklasse mit dem Stereotyp <code>«metaclass»</code>, die das öffentliche Attribut <code>+ value: String</code> deklariert.\n</li><li><code>LiteralIdentifier</code>: Eigene Metaklasse, die über eine gerichtete Abhängigkeit mit dem Stereotyp <code>«extends»</code> die Metaklasse <code>Kernel::LiteralString</code> erweitert.\n</li></ul>\n<p class=\"fig-p\">Zwischen <code>Identifier</code> und den anderen beiden Elementen ist im Diagramm keine direkte Beziehung modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es sind keine dynamischen Interaktionen, Zustandsübergänge oder Sequenzabläufe dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der primitive Typ <code>Identifier</code> dient als Basistyp für Bezeichner im AUTOSAR-Metamodell. Die Modellierung von <code>LiteralIdentifier</code> als Erweiterung (<code>«extends»</code>) von <code>Kernel::LiteralString</code> mit dem Attribut <code>value: String</code> definiert die syntaktische und typbezogene Repräsentation von Literalwerten für Bezeichner auf Metamodell-Ebene. Werkzeug- und Codegeneratoren müssen Bezeichner gemäß diesen Metamodell-Vorgaben als spezialisierte Literalstrings abbilden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4dd8943f40e41e95", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb des AUTOSAR-Vorlagenmodells (Template Modeling Guide). Das Diagramm definiert den primitiven Datentyp <code>Identifier</code> sowie die Metaklasse <code>LiteralIdentifier</code> im Kontext der Profil-Erweiterung von UML-Kerntypen (<code>Kernel::LiteralString</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst drei Entitäten:</p>\n<ul class=\"fig-list\"><li><code>Identifier</code>: Primitiver Datentyp mit dem Stereotyp <code>«primitive»</code>, ohne explizit dargestellte Attribute oder Operationen.\n</li><li><code>Kernel::LiteralString</code>: Externe Metaklasse mit dem Stereotyp <code>«metaclass»</code>, die das öffentliche Attribut <code>+ value: String</code> deklariert.\n</li><li><code>LiteralIdentifier</code>: Eigene Metaklasse, die über eine gerichtete Abhängigkeit mit dem Stereotyp <code>«extends»</code> die Metaklasse <code>Kernel::LiteralString</code> erweitert.\n</li></ul>\n<p class=\"fig-p\">Zwischen <code>Identifier</code> und den anderen beiden Elementen ist im Diagramm keine direkte Beziehung modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es sind keine dynamischen Interaktionen, Zustandsübergänge oder Sequenzabläufe dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der primitive Typ <code>Identifier</code> dient als Basistyp für Bezeichner im AUTOSAR-Metamodell. Die Modellierung von <code>LiteralIdentifier</code> als Erweiterung (<code>«extends»</code>) von <code>Kernel::LiteralString</code> mit dem Attribut <code>value: String</code> definiert die syntaktische und typbezogene Repräsentation von Literalwerten für Bezeichner auf Metamodell-Ebene. Werkzeug- und Codegeneratoren müssen Bezeichner gemäß diesen Metamodell-Vorgaben als spezialisierte Literalstrings abbilden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ea3c11546cb443d1", "to": "FIG-99a5aeab3f3843ab", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-99a5aeab3f3843ab", "to": "FIG-c8cda682e56bd53e", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c8cda682e56bd53e", "to": "FIG-4dd8943f40e41e95", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
